using System.ComponentModel.DataAnnotations;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;
namespace MediStock.Pages.Profile;[Authorize]public sealed class EditModel(AuthService auth):PageModel{[BindProperty]public ProfileInput Input{get;set;}=new();public IActionResult OnGet(){var email=User.FindFirst(System.Security.Claims.ClaimTypes.Email)?.Value;if(string.IsNullOrWhiteSpace(email))return RedirectToPage("/Account/Login");var p=auth.GetProfile(email);if(p is null)return NotFound();Input=new ProfileInput{FullName=p.FullName,PhoneNumber=p.PhoneNumber,PharmacyName=p.PharmacyName};return Page();}public IActionResult OnPost(){var email=User.FindFirst(System.Security.Claims.ClaimTypes.Email)?.Value;if(string.IsNullOrWhiteSpace(email))return RedirectToPage("/Account/Login");if(!string.IsNullOrWhiteSpace(Input.NewPassword)&&Input.NewPassword!=Input.ConfirmPassword){ModelState.AddModelError("Input.ConfirmPassword","The passwords do not match.");return Page();}if(!auth.UpdateProfile(email,Input.FullName.Trim(),Input.PhoneNumber.Trim(),Input.PharmacyName.Trim())){ModelState.AddModelError(string.Empty,"Profile could not be updated.");return Page();}if(!string.IsNullOrWhiteSpace(Input.NewPassword)){if(!auth.ChangePassword(email,Input.CurrentPassword??"",Input.NewPassword)){ModelState.AddModelError("Input.CurrentPassword","Current password is incorrect.");return Page();}}TempData["StatusMessage"]="Profile changes saved.";return RedirectToPage("Index");}}
public sealed class ProfileInput{[Required,StringLength(100)]public string FullName{get;set;}="";[Required,Phone,StringLength(30)]public string PhoneNumber{get;set;}="";[Required,StringLength(120)]public string PharmacyName{get;set;}="";public string?CurrentPassword{get;set;}[StringLength(128,MinimumLength=10)]public string?NewPassword{get;set;}public string?ConfirmPassword{get;set;}}
